import{_ as e,o as i,c as t,ag as s}from"./chunks/framework.Dx86EdC1.js";const g=JSON.parse('{"title":"Peta & Aset Desa (Web GIS)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/gis.md","filePath":"panduan-pengguna/gis.md","lastUpdated":1791382762000}'),n={name:"panduan-pengguna/gis.md"};function l(r,a,d,o,u,p){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="peta-aset-desa-web-gis" tabindex="-1">Peta &amp; Aset Desa (Web GIS) <a class="header-anchor" href="#peta-aset-desa-web-gis" aria-label="Permalink to &quot;Peta &amp; Aset Desa (Web GIS)&quot;">​</a></h1><p>Menu <strong>Peta &amp; Aset</strong> mengelola pemetaan wilayah administratif dan fasilitas desa, sesuai <strong>Permendagri No. 1/2016</strong> (Pengelolaan Aset Desa).</p><h2 id="batas-wilayah-admin-boundaries" tabindex="-1">Batas Wilayah (<code>/admin/boundaries</code>) <a class="header-anchor" href="#batas-wilayah-admin-boundaries" aria-label="Permalink to &quot;Batas Wilayah (`/admin/boundaries`)&quot;">​</a></h2><p>Kelola poligon/titik batas:</p><ul><li><strong>Dusun</strong>, <strong>RW</strong>, <strong>RT</strong>, dan batas desa.</li><li>Input geometri (koordinat) untuk divisualisasikan di peta publik.</li></ul><p>Tersedia filter batas per jenis wilayah; publik melihatnya di <strong><code>/peta</code></strong>.</p><h2 id="fasilitas-aset-desa-admin-facilities" tabindex="-1">Fasilitas &amp; Aset Desa (<code>/admin/facilities</code>) <a class="header-anchor" href="#fasilitas-aset-desa-admin-facilities" aria-label="Permalink to &quot;Fasilitas &amp; Aset Desa (`/admin/facilities`)&quot;">​</a></h2><p>Titik lokasi infrastruktur dan fasilitas umum:</p><ul><li>Fasilitas umum (masjid, balai desa, sekolah, posyandu, dll).</li><li><strong>Aset desa</strong> dengan atribut yuridis: <ul><li><strong>Status hak kepemilikan</strong>: Tanah Kas Desa (TKD), Hibah, APBDes, dll.</li><li><strong>Kode register inventaris barang (KIB)</strong> A s.d. F.</li></ul></li></ul><h3 id="field-gambar-dual-mode" tabindex="-1">Field Gambar (Dual-Mode) <a class="header-anchor" href="#field-gambar-dual-mode" aria-label="Permalink to &quot;Field Gambar (Dual-Mode)&quot;">​</a></h3><p>Sama seperti modul konten: unggah berkas (<code>image_file</code>) <strong>atau</strong> masukkan <code>image_url</code> eksternal. Berkas lama otomatis dibersihkan saat diganti/dihapus.</p><h2 id="tampilan-publik-peta" tabindex="-1">Tampilan Publik (<code>/peta</code>) <a class="header-anchor" href="#tampilan-publik-peta" aria-label="Permalink to &quot;Tampilan Publik (`/peta`)&quot;">​</a></h2><p>Peta interaktif menampilkan:</p><ul><li>Batas wilayah administratif desa (dusun/RW/RT).</li><li>Lokasi fasilitas &amp; aset beserta atributnya.</li></ul><div class="tip custom-block"><p class="custom-block-title">Akurasi</p><p>Koordinat diambil dari GPS/layanan pemetaan resmi. Untuk aset tanah, cocokkan dengan sertifikat/letter C sebelum input status hak kepemilikan.</p></div>',15)])])}const c=e(n,[["render",l]]);export{g as __pageData,c as default};
